<div class="mb-6"><h1 class="text-2xl font-bold text-white">Projects</h1><p class="text-slate-400 mt-1">Organize servers into projects</p></div>
<div class="bg-[#13151f] border border-[#2a2d3e] rounded-xl overflow-hidden"><div class="grid grid-cols-5 px-5 py-3 text-xs uppercase tracking-wide text-slate-500 border-b border-[#2a2d3e]"><div>Name</div><div>Description</div><div>Servers</div><div>Owner</div><div>Created</div></div><?php foreach ($rows as $row): ?><div class="grid grid-cols-5 px-5 py-3 text-sm border-b border-[#1e2130] last:border-0"><div class="font-medium text-white"><?php echo html_escape($row['name']); ?></div><div class="text-slate-500 text-xs"><?php echo html_escape($row['description']); ?></div><div class="text-slate-400"><?php echo (int) $row['servers_count']; ?></div><div class="text-slate-400"><?php echo html_escape($row['owner']); ?></div><div class="text-slate-400"><?php echo html_escape(substr($row['created_at'], 0, 10)); ?></div></div><?php endforeach; ?></div>
